// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: positive amounts that exceed the contract's holdings
        vm.deal(address(c), 1 wei);
        amount = bound(amount, 2, type(uint256).max);

        // c's owner is this test contract (msg.sender at deployment); give it a
        // payable receive so transfer success is governed only by the balance.
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }

        // General rule: withdrawing more ether than c holds must revert.
        // Reference: transfer(amount) fails (insufficient balance) -> ok == false.
        // Mutant: the transfer statement is deleted, so the call silently succeeds.
        assertTrue(!ok, "withdraw of more than balance must revert");
    }

    receive() external payable {}
}
